// Edit sources and filters; keep dryRun true to preview without publishing.
return [{json: {
  dryRun: true,
  visibility: 'CHOOSE',
  acknowledgeWriteOnce: false,
  title: 'Dependency release digest',
  repositories: ['n8n-io/n8n', 'nodejs/node'],
  lookbackDays: 7,
  includePrereleases: false,
  maxReleasesPerRepository: 3,
  ttlDays: 1
}}];

const c = $json;
if (typeof c.dryRun !== 'boolean') throw new Error('dryRun must be boolean');
if (typeof c.title !== 'string' || !c.title.trim() || c.title.length > 180) throw new Error('Title is required (1-180 characters)');
if (c.ttlDays !== 1) throw new Error('Write-once reports must expire after exactly 1 day');
if (!c.dryRun && !['public','unlisted'].includes(c.visibility)) throw new Error('Explicitly choose public or unlisted before publishing');
if (!c.dryRun && c.acknowledgeWriteOnce !== true) throw new Error('Acknowledge write-once publishing: owner capability is not retained; cannot update/delete via this workflow');
if (!Array.isArray(c.repositories) || c.repositories.length < 1 || c.repositories.length > 5) throw new Error('Choose 1-5 public repositories');
if (c.repositories.some(r => typeof r !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9-]{0,38}\/[A-Za-z0-9_.-]{1,100}$/.test(r) || ['.','..'].includes(r.split('/')[1]))) throw new Error('Repository must be owner/repo, not a URL');
if (new Set(c.repositories.map(r => r.toLowerCase())).size !== c.repositories.length) throw new Error('Repositories must be unique');
if (!Number.isInteger(c.lookbackDays) || c.lookbackDays < 1 || c.lookbackDays > 30) throw new Error('lookbackDays must be 1-30');
if (typeof c.includePrereleases !== 'boolean') throw new Error('includePrereleases must be boolean');
if (!Number.isInteger(c.maxReleasesPerRepository) || c.maxReleasesPerRepository < 1 || c.maxReleasesPerRepository > 5) throw new Error('maxReleasesPerRepository must be 1-5');
return c.repositories.map(repository => ({json: {repository, endpoint: 'https://api.github.com/repos/' + repository + '/releases?per_page=20'}}));

const c = $('Report inputs').first().json;
const sources = $('Validate sources').all();
const responses = $input.all();
if (responses.length !== sources.length) throw new Error('Expected one response per repository');
const now = new Date();
const cutoff = now.getTime() - c.lookbackDays * 86400000;
const escape = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const excerpt = body => String(body || '').replace(/```[\s\S]*?```/g, ' [code omitted] ').replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/\[([^\]]+)\]\([^)]*\)/g, '$1').replace(/<[^>]*>/g, ' ').replace(/[#*_`~]/g, '').replace(/\s+/g, ' ').trim().slice(0, 400);
const seen = new Set();
let releaseCount = 0;
const groups = responses.map((item, index) => {
  const repository = sources[index].json.repository;
  const response = item.json;
  if (response.statusCode !== 200 || !Array.isArray(response.body)) throw new Error('Invalid GitHub release response for ' + repository);
  const prefix = 'https://github.com/' + repository + '/releases/tag/';
  const releases = response.body.filter(release => {
    if (!release || release.draft !== false || typeof release.prerelease !== 'boolean') return false;
    if (!c.includePrereleases && release.prerelease) return false;
    const date = Date.parse(release.published_at);
    if (!Number.isFinite(date) || date < cutoff || date > now.getTime()) return false;
    if (typeof release.html_url !== 'string' || !release.html_url.toLowerCase().startsWith(prefix.toLowerCase()) || !/^https:\/\/github\.com\/[^\s?#"'<>]+$/.test(release.html_url)) throw new Error('Unexpected GitHub release source URL');
    return true;
  }).sort((a,b) => Date.parse(b.published_at) - Date.parse(a.published_at)).filter(release => {
    const key = release.html_url.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).slice(0, c.maxReleasesPerRepository);
  releaseCount += releases.length;
  const rows = releases.map(release => '<article><h3><a href="' + escape(release.html_url) + '">' + escape(String(release.name || release.tag_name || 'Release').slice(0,180)) + '</a></h3><p>' + escape(release.tag_name || '') + ' · ' + escape(new Date(release.published_at).toISOString().slice(0,10)) + (release.prerelease ? ' · prerelease' : '') + '</p><p>' + escape(excerpt(release.body) || 'No release notes supplied.') + '</p></article>').join('');
  return '<section><h2><a href="https://github.com/' + escape(repository) + '/releases">' + escape(repository) + '</a></h2>' + (rows || '<p>No matching releases in the fetched window.</p>') + (response.body.length >= 20 ? '<p>Fetch limit reached: only the first 20 releases were checked; the requested date window may be incomplete.</p>' : '') + '</section>';
});
const content = '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + escape(c.title) + '</title><style>body{font:16px/1.6 system-ui,sans-serif;max-width:860px;margin:40px auto;padding:0 20px;color:#1f2937;background:#fff}a{color:#0757a6}section{margin:28px 0;border-top:1px solid #d1d5db}article{margin:20px 0}h3{margin-bottom:0}p{overflow-wrap:anywhere}</style><h1>' + escape(c.title) + '</h1><p>' + releaseCount + ' matching releases from ' + sources.length + ' repositories. Last ' + c.lookbackDays + ' days; generated ' + now.toISOString() + '.</p><p>Release-note excerpts are shortened plain text, not AI summaries. Read each linked source before upgrading.</p>' + groups.join('') + '<footer>Public GitHub releases; first 20 per repository, up to ' + c.maxReleasesPerRepository + ' matches each. This shared report expires after one day.</footer></html>';
return [{json: {...c, content, format: 'html', releaseCount, sourceCount: sources.length}}];

const c = $json;
if (typeof c.dryRun !== 'boolean') throw new Error('dryRun must be boolean');
if (typeof c.title !== 'string' || !c.title.trim() || c.title.length > 180) throw new Error('Title is required (1-180 characters)');
if (c.ttlDays !== 1) throw new Error('Write-once reports must expire after exactly 1 day');
if (!c.dryRun && !['public','unlisted'].includes(c.visibility)) throw new Error('Explicitly choose public or unlisted before publishing');
if (!c.dryRun && c.acknowledgeWriteOnce !== true) throw new Error('Acknowledge write-once publishing: owner capability is not retained; cannot update/delete via this workflow');
if (typeof c.content !== 'string' || !c.content.trim()) throw new Error('Content is required');
const endpoint = 'https://brewpage.app/api/html';
const query = {ttl: String(c.ttlDays)};
if (c.visibility === 'public') query.ns = 'public';
const filename = 'report-' + c.title.replace(/[\/\\\x00-\x1f\x7f]/g, '-').trim() + '.html';
return [{json: {dryRun: c.dryRun, endpoint, query, body: {content: c.content, format: 'html', filename}, releaseCount: c.releaseCount, sourceCount: c.sourceCount}}];

const link = $json.link;
if (typeof link !== 'string') throw new Error('Publish response has no reader link');
const publicPath = /^https:\/\/brewpage\.app\/public\/[A-Za-z0-9]{10}$/.test(link);
const match = /^https:\/\/((?:[a-z0-9]{10}|[a-z0-9][a-z0-9-]{0,32}-[a-z0-9]{10}))\.brewpage\.app\/$/.exec(link);
const reserved = new Set(['unlock','www','api','admin','assets','static','cdn','status','health','metrics','grafana','prometheus','monitoring','autoconfig','autodiscover','fe-bounces','account']);
if (!publicPath && (!match || reserved.has(match[1]))) throw new Error('Unexpected reader URL');
return [{json: {url: link}}];
